import * as React from "react"
import { Link } from "gatsby"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import * as s from "./SaveToAccount.module.css"

/**
 * Keeping an invoice or a QR code — FCS-075.
 * ============================================================================
 * A strip above the tool: name it, save it, and it is in the account. The
 * same component for both, because the only thing that differs is the word
 * on the button.
 *
 * ── THE TOOLS STILL WORK SIGNED OUT ───────────────────────────────────────
 * Both of these have always been free to use with no account at all, and that
 * does not change. Signed out, this strip is one line offering an account
 * rather than a wall — somebody who came to make one QR code for a van should
 * get their QR code.
 *
 * ── SAVE AND SAVE-AGAIN ARE DIFFERENT ─────────────────────────────────────
 * Once something has been saved, the button updates THAT record rather than
 * making a second copy. Otherwise pressing save twice leaves two, and the
 * list fills with "Kitchen job", "Kitchen job", "Kitchen job" — which is how
 * a plan limit gets hit by somebody who saved one invoice.
 *
 * ── ONE TOOLBAR, NOT TWO ROWS OF ODDMENTS — FCS-102 ────────────────────────
 * The page's own actions used to sit on a different row (a text link and a
 * button in the preview bar) from the save controls (a button and a text link
 * in the name bar), so the same few things were scattered over two places in
 * three different styles. They are now one bar: the name on the left, the
 * actions together on the right, and three levels of weight —
 *
 *   quiet     New invoice, Saved invoices      (things you do now and then)
 *   outlined  Save to my account               (keeping it)
 *   solid     Download PDF                     (the thing most people came for)
 *
 * The page hands its own actions in as `tools` (quiet) and `primary` (solid),
 * so this component lays them out and the page does not have to know about
 * either state of sign-in. They are present signed in, signed out, and before
 * the session is known: Download must never wait on an account check.
 *
 * ── A FULL PLAN IS EXPLAINED, NOT JUST REFUSED ────────────────────────────
 * The server answers 409 with the actual numbers (FCS-073(b)); they go on
 * screen as they came, because "limit reached" tells nobody whether to
 * delete one thing or upgrade.
 */

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token
  if (!token) return { ok: false, status: 401, body: {} }

  const res = await fetch(apiUrl("my-documents"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

/**
 * Loads `?open=<id>` into a tool, once.
 *
 * Returns the saved record's id and name so the tool's save strip updates
 * that record instead of making a copy of it — opening something and
 * pressing save should leave one of it, not two.
 */
export function useOpenSaved(onLoad) {
  const [opened, setOpened] = React.useState({ id: "", name: "" })
  const [error, setError] = React.useState("")
  const done = React.useRef(false)

  React.useEffect(() => {
    if (done.current || typeof window === "undefined") return
    const id = new URLSearchParams(window.location.search).get("open")
    if (!id) return
    done.current = true

    let alive = true
    ;(async () => {
      const res = await call({ action: "open", id })
      if (!alive) return
      if (!res.ok) {
        setError(
          res.status === 401
            ? "Log in to open something you saved."
            : res.body.message || "That could not be opened."
        )
        return
      }
      const doc = res.body.document
      if (doc?.data) {
        onLoad(doc.data)
        setOpened({ id: doc.id, name: doc.name })
      }
    })()
    return () => {
      alive = false
    }
    // Deliberately once: re-running this would throw away whatever the
    // customer has typed since it loaded.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return { opened, openError: error }
}

/**
 * `tools`    [{ label, onClick, ariaLabel? }]  quiet actions, before Save
 * `primary`  { label, onClick }                the solid action, last
 */
const SaveToAccount = ({ kind, data, opened, suggestedName, tools = [], primary = null }) => {
  const [signedIn, setSignedIn] = React.useState(null)
  const [id, setId] = React.useState("")
  const [name, setName] = React.useState("")
  const [state, setState] = React.useState({ status: "", message: "", code: "" })

  React.useEffect(() => {
    const client = supabase()
    if (!client) {
      setSignedIn(false)
      return undefined
    }
    let alive = true
    client.auth.getSession().then(({ data: session }) => {
      if (alive) setSignedIn(Boolean(session?.session?.access_token))
    })
    return () => {
      alive = false
    }
  }, [])

  /* Opening a saved record adopts its id and name, so the next save updates
     it rather than copying it. */
  React.useEffect(() => {
    if (opened?.id) {
      setId(opened.id)
      setName(opened.name || "")
    }
  }, [opened?.id, opened?.name])

  const save = async event => {
    event?.preventDefault()
    const chosen = (name || suggestedName || "").trim()
    if (!chosen) {
      setState({ status: "bad", message: "Give it a name so you can find it again." })
      return
    }

    setState({ status: "saving", message: "", code: "" })
    const res = await call({ action: "save", id: id || undefined, kind, name: chosen, data })

    if (!res.ok) {
      setState({
        status: "bad",
        // "plan-locked": the plan does not keep these, so the message offers the plans.
        code: res.body.code || "",
        message:
          res.status === 401
            ? "Log in to save this to your account."
            : res.body.message || "That did not save.",
      })
      return
    }

    if (res.body.document?.id) setId(res.body.document.id)
    setName(chosen)
    setState({ status: "ok", message: res.body.created ? "Saved." : "Updated.", code: "" })
    setTimeout(
      () => setState(st => (st.status === "ok" ? { status: "", message: "", code: "" } : st)),
      2200
    )
  }

  const section = kind === "qr" ? "qrs" : "invoices"
  const noun = kind === "qr" ? "QR codes" : "invoices"

  const quiet = tools.map(tool => (
    <button
      key={tool.label}
      type="button"
      className={s.ghost}
      onClick={tool.onClick}
      aria-label={tool.ariaLabel || undefined}
    >
      {tool.label}
    </button>
  ))
  const solid = primary ? (
    <button type="button" className={s.solid} onClick={primary.onClick}>
      {primary.label}
    </button>
  ) : null

  // Until the session is known there is no name field to draw; the page's own actions still are.
  if (signedIn === null) {
    return (
      <div className={s.bar}>
        <span />
        <div className={s.actions}>
          {quiet}
          {solid}
        </div>
      </div>
    )
  }

  if (!signedIn) {
    return (
      <div className={s.bar}>
        <p className={s.offer}>
          <Link to="/sign-up/">Create a free account</Link> to save this and come back to it later.
          Everything here works without one.
        </p>
        <div className={s.actions}>
          {quiet}
          {solid}
        </div>
      </div>
    )
  }

  return (
    <form className={s.bar} onSubmit={save}>
      <div className={s.field}>
        <label className={s.label} htmlFor={`save-${kind}`}>
          Name
        </label>
        <input
          id={`save-${kind}`}
          className={s.input}
          value={name}
          onChange={event => setName(event.target.value)}
          placeholder={suggestedName || "Give it a name"}
          maxLength={120}
        />
      </div>

      <div className={s.actions}>
        {quiet}
        <Link className={s.ghost} to={`/account/#${section}`}>
          Saved {noun}
        </Link>
        <button type="submit" className={s.outlined} disabled={state.status === "saving"}>
          {state.status === "saving" ? "Saving…" : id ? "Save changes" : "Save to my account"}
        </button>
        {solid}
      </div>

      {state.message ? (
        <p className={s.msg} data-tone={state.status === "ok" ? "ok" : "bad"} role="status">
          {state.message}
          {state.code === "plan-locked" ? (
            <>
              {" "}
              <Link to={`/account/#${section}`}>See plans</Link>
            </>
          ) : null}
        </p>
      ) : null}
    </form>
  )
}

export default SaveToAccount
