import * as React from "react"
import { formatDate, money } from "../../../lib/invoice"
import { prepare, MailIcon, PhoneIcon } from "./shared"
import * as s from "./Signature.module.css"

/**
 * SIGNATURE — curved header, an accent strip for the reference, a payment box
 * and a signed foot.
 *
 * Four structural moves nothing else here uses:
 *
 *  1. The dark header has a large curved corner and carries a GHOSTED
 *     "INVOICE" inside it, rather than the word sitting in a block of its own.
 *  2. A rounded pill of contact details overlaps its right-hand edge.
 *  3. The reference and date get their own ACCENT STRIP under the header
 *     instead of a column of labels beside the client.
 *  4. The foot is split: a bordered, tinted payment box on the left and a
 *     signed-off block on the right.
 *
 * The items table is completely unfilled — the header, the strip and the
 * payment box are already three weighted elements, and a fourth would leave
 * nowhere for the eye to rest.
 *
 * ── HOURS, NOT QUANTITY ────────────────────────────────────────────────────
 * The column reads "Hours" because this layout suits time-billed work, which
 * is what a quantity usually IS on a contractor's invoice. It is the same
 * number the other designs label "Qty" — no second field, no second sum.
 */
const Signature = ({ invoice, t }) => {
  const v = prepare(invoice)

  // The box shows one payment: it is a receipt block, not a ledger. A second
  // payment belongs on a design that has a table for them.
  const payment = (invoice.payments || []).find(
    p => p.method.trim() || p.reference.trim() || Number(p.amount)
  )
  const sig = invoice.signature || { name: "", title: "" }

  return (
    <div
      className={s.page}
      style={{ "--c": t.primary, "--on-c": t.onPrimary, "--a": t.accent, "--ink": t.ink, "--surface": t.surface }}
    >
      <header className={s.head}>
        <div className={s.curve}>
          <div className={s.brand}>
            {invoice.from.logo ? (
              <img src={invoice.from.logo} alt="" className={s.logo} />
            ) : (
              <span className={s.brandName}>{invoice.from.name || ""}</span>
            )}
          </div>
          <span className={s.ghost} aria-hidden="true">
            Invoice
          </span>
        </div>

        {(invoice.from.phone.trim() || invoice.from.email.trim()) && (
          <div className={s.pill}>
            {invoice.from.phone.trim() ? (
              <span>
                <PhoneIcon />
                {invoice.from.phone}
              </span>
            ) : null}
            {invoice.from.email.trim() ? (
              <span>
                <MailIcon />
                {invoice.from.email}
              </span>
            ) : null}
          </div>
        )}
      </header>

      {(invoice.number.trim() || v.issued || v.due) && (
        <div className={s.strip}>
          {invoice.number.trim() ? (
            <span>
              <strong>Invoice No:</strong> {invoice.number}
            </span>
          ) : null}
          {v.issued ? (
            <span>
              <strong>Invoice Date:</strong> {v.issued}
            </span>
          ) : null}
          {v.due ? (
            <span>
              <strong>Due:</strong> {v.due}
            </span>
          ) : null}
        </div>
      )}

      <div className={s.body}>
        <section className={s.parties}>
          <div>
            <p className={s.partyLabel}>Invoice To:</p>
            {invoice.to.name.trim() ? <p className={s.partyName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.partyLine}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.partyLine}>{invoice.to.email}</p> : null}
          </div>
          <div className={s.right}>
            <p className={s.partyLabel}>Pay To:</p>
            {invoice.from.name.trim() ? <p className={s.partyName}>{invoice.from.name}</p> : null}
            {invoice.from.address.trim() ? (
              <p className={s.partyLine}>{invoice.from.address}</p>
            ) : null}
            {invoice.from.email.trim() ? <p className={s.partyLine}>{invoice.from.email}</p> : null}
          </div>
        </section>

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colNo}>S. No.</th>
              <th className={s.colDesc}>Description</th>
              <th className={s.colPrice}>Price</th>
              <th className={s.colHours}>Hours</th>
              <th className={s.colTotal}>Total</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={5} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map((line, i) => (
                <tr key={line.id}>
                  <td className={s.colNo}>{i + 1}</td>
                  <td className={s.colDesc}>
                    <span className={s.itemTitle}>{line.title}</span>
                    {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                  </td>
                  <td className={s.colPrice}>{v.fmt(line.rate)}</td>
                  <td className={s.colHours}>{Number(line.quantity) || 0}</td>
                  <td className={s.colTotal}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.mid}>
          <div className={s.terms}>
            {invoice.terms.trim() ? (
              <>
                <p className={s.termsTitle}>Terms &amp; Conditions:</p>
                <p className={s.termsText}>{invoice.terms}</p>
              </>
            ) : null}
            {invoice.notes.trim() ? (
              <>
                <p className={s.termsTitle}>Additional Information:</p>
                <p className={s.termsText}>{invoice.notes}</p>
              </>
            ) : null}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasDiscount ? (
              <p>
                <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
                <span>− {v.fmt(v.sums.discount)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>− {v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>{v.hasPaid ? "Balance Due:" : "Grand Total:"}</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>

        <section className={s.foot}>
          {payment ? (
            <dl className={s.payBox}>
              {payment.method.trim() ? (
                <div>
                  <dt>Payment Details:</dt>
                  <dd>{payment.method}</dd>
                </div>
              ) : null}
              {payment.date ? (
                <div>
                  <dt>Date:</dt>
                  <dd>{formatDate(payment.date)}</dd>
                </div>
              ) : null}
              {payment.reference.trim() ? (
                <div>
                  <dt>Transaction ID:</dt>
                  <dd>{payment.reference}</dd>
                </div>
              ) : null}
              {Number(payment.amount) ? (
                <div>
                  <dt>Amount:</dt>
                  <dd>{money(payment.amount, v.currency)}</dd>
                </div>
              ) : null}
            </dl>
          ) : (
            <span />
          )}

          {sig.name.trim() ? (
            <div className={s.sign}>
              <p className={s.signMark}>{sig.name}</p>
              <p className={s.signName}>{sig.name}</p>
              {sig.title.trim() ? <p className={s.signTitle}>{sig.title}</p> : null}
            </div>
          ) : null}
        </section>
      </div>
    </div>
  )
}

export default Signature
