import * as React from "react"
import { formatDate, money } from "../../../lib/invoice"
import { prepare, MailIcon, PhoneIcon } from "./shared"
import * as s from "./Detailed.module.css"

/**
 * DETAILED — a split header, a job-details grid, and payments received.
 *
 * Structurally the opposite of Standard in three ways, which is what makes it
 * a second design rather than a recolour:
 *
 *  1. The reference numbers live INSIDE the header, in the dark half, instead
 *     of in a block under it. That buys back a whole band of vertical space.
 *  2. A bordered grid carries whatever the job needs recording — job number,
 *     dates, permit, site. Free label/value pairs, because the useful six
 *     differ by trade.
 *  3. Payments already received get their own small table at the foot, so a
 *     part-paid invoice shows WHAT was paid and when rather than one
 *     unexplained "paid" line in the totals.
 *
 * The items table is deliberately unfilled here — the header and the grid
 * already carry the weight, and a dark table head on top of both would be a
 * third heavy element competing with them.
 *
 * Blocks with no data render nothing at all. An empty grid is worse than no
 * grid, because it looks like something failed to load.
 */
const Detailed = ({ invoice, t }) => {
  const v = prepare(invoice)

  const details = (invoice.details || []).filter(d => d.label.trim() || d.value.trim())
  const payments = (invoice.payments || []).filter(
    p => p.method.trim() || p.reference.trim() || Number(p.amount)
  )

  return (
    <div className={s.page} style={{ "--c": t.primary, "--on-c": t.onPrimary, "--ink": t.ink, "--surface": t.surface }}>
      <header className={s.band}>
        <div className={s.brand}>
          {invoice.from.logo ? (
            <img src={invoice.from.logo} alt="" className={s.logo} />
          ) : (
            <span className={s.brandName}>{invoice.from.name || ""}</span>
          )}
        </div>

        <div className={s.bandDark}>
          <span className={s.ghost} aria-hidden="true">
            INV
          </span>
          <dl className={s.meta}>
            {invoice.number.trim() ? (
              <>
                <dt>Invoice No:</dt>
                <dd>{invoice.number}</dd>
              </>
            ) : null}
            {v.issued ? (
              <>
                <dt>Invoice Date:</dt>
                <dd>{v.issued}</dd>
              </>
            ) : null}
            {v.due ? (
              <>
                <dt>Due Date:</dt>
                <dd>{v.due}</dd>
              </>
            ) : null}
          </dl>
        </div>
      </header>

      <div className={s.body}>
        <section className={s.parties}>
          <div>
            <p className={s.partyLabel}>Client Info:</p>
            {invoice.to.name.trim() ? <p className={s.partyName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.partyLine}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.partyLine}>{invoice.to.email}</p> : null}
          </div>
          <div className={s.right}>
            <p className={s.partyLabel}>Business Details:</p>
            {invoice.from.name.trim() ? <p className={s.partyName}>{invoice.from.name}</p> : null}
            {invoice.from.address.trim() ? (
              <p className={s.partyLine}>{invoice.from.address}</p>
            ) : null}
            {invoice.from.phone.trim() ? <p className={s.partyLine}>{invoice.from.phone}</p> : null}
            {invoice.from.email.trim() ? <p className={s.partyLine}>{invoice.from.email}</p> : null}
          </div>
        </section>

        {details.length > 0 && (
          <section className={s.grid}>
            {details.slice(0, 6).map(d => (
              <div key={d.id} className={s.cell}>
                <span className={s.cellLabel}>{d.label}</span>
                <span className={s.cellValue}>{d.value}</span>
              </div>
            ))}
          </section>
        )}

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colItem}>Items</th>
              <th className={s.colDesc}>Description</th>
              <th className={s.colRate}>Rate</th>
              <th className={s.colAmount}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={4} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map(line => (
                <tr key={line.id}>
                  <td className={s.colItem}>{line.title}</td>
                  <td className={s.colDesc}>{line.rest}</td>
                  <td className={s.colRate}>
                    {Number(line.quantity) === 1
                      ? v.fmt(line.rate)
                      : `${Number(line.quantity) || 0} × ${v.fmt(line.rate)}`}
                  </td>
                  <td className={s.colAmount}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
            {v.hasDiscount ? (
              <tr>
                <td className={s.colItem}>Discount</td>
                <td className={s.colDesc}>
                  {v.discountPct ? `${v.discountPct}% off the subtotal` : "Applied to the subtotal"}
                </td>
                <td className={s.colRate}>{v.discountPct ? `${v.discountPct}% OFF` : ""}</td>
                <td className={s.colAmount}>−{v.fmt(v.sums.discount)}</td>
              </tr>
            ) : null}
          </tbody>
        </table>

        <section className={s.foot}>
          <div className={s.notes}>
            {invoice.notes.trim() ? (
              <>
                <p className={s.notesTitle}>Additional Information:</p>
                <p className={s.notesText}>{invoice.notes}</p>
              </>
            ) : null}
            {invoice.terms.trim() ? (
              <>
                <p className={s.notesTitle}>Terms:</p>
                <p className={s.notesText}>{invoice.terms}</p>
              </>
            ) : null}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>−{v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>{v.hasPaid ? "Balance Due:" : "Grand Total:"}</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>

        {payments.length > 0 && (
          <table className={s.payments}>
            <thead>
              <tr>
                <th>Payment Details</th>
                <th>Date</th>
                <th>Transaction ID</th>
                <th className={s.colAmount}>Amount</th>
              </tr>
            </thead>
            <tbody>
              {payments.map(p => (
                <tr key={p.id}>
                  <td>{p.method}</td>
                  <td>{formatDate(p.date)}</td>
                  <td>{p.reference}</td>
                  <td className={s.colAmount}>{money(p.amount, v.currency)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <footer className={s.bandFoot}>
        {invoice.from.phone.trim() ? (
          <span>
            <PhoneIcon />
            {invoice.from.phone}
          </span>
        ) : (
          <span />
        )}
        {invoice.from.email.trim() ? (
          <span>
            <MailIcon />
            {invoice.from.email}
          </span>
        ) : null}
      </footer>
    </div>
  )
}

export default Detailed
