/**
 * THE INVOICE MODEL — MTC-FCS-003.
 * ============================================================================
 * One object describing an invoice, the arithmetic over it, and the rules for
 * keeping it in this browser. The form writes it, the document renders it, and
 * neither one does sums of its own.
 *
 * ── MONEY IS HELD IN CENTS ─────────────────────────────────────────────────
 * Rates and totals are integers of the minor unit, never floats. 0.1 + 0.2 is
 * not 0.3 in binary floating point, and on an invoice that surfaces as a total
 * that disagrees with the lines above it by a cent — which is the single
 * fastest way to lose a customer's trust in a document about money.
 *
 * Quantity IS allowed decimals (3.5 hours, 2.25 tons), so line totals round
 * once, at the line, using half-up — the convention people expect on a bill.
 */

export const CURRENCIES = [
  { code: "USD", symbol: "$", label: "US Dollar" },
  { code: "EUR", symbol: "€", label: "Euro" },
  { code: "GBP", symbol: "£", label: "British Pound" },
  { code: "CAD", symbol: "$", label: "Canadian Dollar" },
  { code: "AUD", symbol: "$", label: "Australian Dollar" },
]

let seq = 0
/** Ids only have to be unique within one document in one browser. */
export function lineId() {
  seq += 1
  return `line-${Date.now().toString(36)}-${seq}`
}

export function emptyLine() {
  // `period` is free text, not a date range: "01-31 May", "Week 12", "Mar-Apr"
  // and "3 visits" are all things a contractor writes there, and a date picker
  // would refuse most of them. Optional, and ignored by designs with no column
  // for it.
  return { id: lineId(), description: "", quantity: 1, rate: 0, period: "" }
}

/**
 * A label/value pair for the job-details grid — "Job No", "Started",
 * "Permit", whatever the trade needs. Free text on both sides rather than a
 * fixed set of fields, because a roofer's useful six and a plumber's useful
 * six are not the same six and guessing them wrong makes the block dead space.
 */
export function emptyDetail() {
  return { id: lineId(), label: "", value: "" }
}

/** One payment already received against this invoice. */
export function emptyPayment() {
  return { id: lineId(), method: "", date: "", reference: "", amount: 0 }
}

export function emptyInvoice() {
  const today = new Date()
  const due = new Date(today.getTime() + 14 * 24 * 60 * 60 * 1000)
  return {
    version: 1,
    // Two separate choices: the shape of the page, and its two colours.
    layoutId: "agency",
    paletteId: "agency",
    currency: "USD",

    number: "INV-0001",
    issuedOn: toDateInput(today),
    dueOn: toDateInput(due),

    from: { name: "", email: "", phone: "", address: "", logo: "" },
    to: { name: "", email: "", address: "" },

    lines: [emptyLine()],

    // Both optional, and only rendered by designs that have a place for them.
    // An empty one prints nothing at all rather than an empty box.
    details: [],
    payments: [],

    // Percentages are stored as typed (7.5 means 7.5%), converted once here.
    taxRate: 0,
    taxLabel: "Tax",
    discountMode: "none", // none | percent | fixed
    discountValue: 0,
    amountPaid: 0,

    notes: "",
    terms: "Payment due within 14 days.",

    // Optional, and only rendered by designs with a place for it. Name and
    // title only — the signature itself is set in a script face rather than
    // uploaded, because a scanned signature image on a downloadable invoice is
    // a forgeable asset sitting in somebody's downloads folder.
    signature: { name: "", title: "" },
  }
}

export function toDateInput(date) {
  const d = date instanceof Date ? date : new Date(date)
  if (Number.isNaN(d.getTime())) return ""
  // Local, not ISO/UTC: an invoice dated "today" in Denver must not print
  // yesterday's date because the machine is behind UTC.
  const pad = n => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

export function formatDate(value) {
  if (!value) return ""
  const [y, m, d] = String(value).split("-").map(Number)
  if (!y || !m || !d) return value
  return new Date(y, m - 1, d).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  })
}

/** Half-up to the nearest cent — the rounding people expect on a bill. */
function roundCents(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100
}

export function lineTotal(line) {
  const qty = Number(line.quantity) || 0
  const rate = Number(line.rate) || 0
  return roundCents(qty * rate)
}

/**
 * Every number the document prints, computed in one place and in one order.
 * Discount comes off before tax, because tax is charged on what is actually
 * being paid, not on a price that was never charged.
 */
export function totals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0))

  let discount = 0
  if (invoice.discountMode === "percent") {
    discount = roundCents((subtotal * (Number(invoice.discountValue) || 0)) / 100)
  } else if (invoice.discountMode === "fixed") {
    discount = roundCents(Number(invoice.discountValue) || 0)
  }
  // A discount cannot exceed the bill, or the tax line goes negative.
  discount = Math.min(discount, subtotal)

  const taxable = roundCents(subtotal - discount)
  const tax = roundCents((taxable * (Number(invoice.taxRate) || 0)) / 100)
  const total = roundCents(taxable + tax)
  // Payments listed in the payments table and the single "amount already paid"
  // field are the same money seen two ways, so the larger of the two is used
  // rather than their sum — adding them would credit a customer twice.
  const listed = Array.isArray(invoice.payments)
    ? roundCents(invoice.payments.reduce((sum, p) => sum + (Number(p.amount) || 0), 0))
    : 0
  const claimed = Math.max(roundCents(Number(invoice.amountPaid) || 0), listed)
  const paid = Math.min(claimed, total)
  const balance = roundCents(total - paid)

  return { subtotal, discount, taxable, tax, total, paid, balance }
}

export function money(amount, currencyCode = "USD") {
  const value = Number(amount) || 0
  try {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: currencyCode,
    }).format(value)
  } catch {
    // An unknown code should still print a number rather than throwing in the
    // middle of rendering the document.
    return `${currencyCode} ${value.toFixed(2)}`
  }
}

/* ── Persistence ───────────────────────────────────────────────────────────
   This browser only. An invoice carries a customer's name and address, and
   nothing here is worth posting to a server the user did not ask for. */

const STORAGE_KEY = "fcs.invoice.v1"

export function loadInvoice() {
  if (typeof window === "undefined") return null
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const saved = JSON.parse(raw)
    if (!saved || saved.version !== 1) return null
    const base = emptyInvoice()
    // Drafts written before colour and layout were split carry a single
    // `templateId`. It meant both, so it seeds both.
    const legacy = saved.templateId
    return {
      ...base,
      ...(legacy ? { layoutId: "agency", paletteId: legacy } : {}),
      ...saved,
      layoutId: saved.layoutId || (legacy ? "agency" : base.layoutId),
      paletteId: saved.paletteId || legacy || base.paletteId,
      from: { ...base.from, ...saved.from },
      signature: { ...base.signature, ...saved.signature },
      to: { ...base.to, ...saved.to },
      lines: Array.isArray(saved.lines) && saved.lines.length > 0 ? saved.lines : base.lines,
      details: Array.isArray(saved.details) ? saved.details : base.details,
      payments: Array.isArray(saved.payments) ? saved.payments : base.payments,
    }
  } catch {
    return null
  }
}

export function saveInvoice(invoice) {
  if (typeof window === "undefined") return
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(invoice))
  } catch {
    /* Quota or private mode — losing the draft beats throwing mid-keystroke. */
  }
}
