import * as React from "react"
import { formatDate, money } from "../../../lib/invoice"
import { prepare, MailIcon, PhoneIcon, PinIcon } from "./shared"
import * as s from "./Bright.module.css"

/**
 * BRIGHT — a light header with a rounded accent tab.
 *
 * The only design here that does NOT open on a dark band. The issuer's logo
 * and contact rows sit on white at the top-left, and the document names itself
 * in a rounded accent panel on the right with a dark sliver offset behind it —
 * so the weight is one shape rather than a full-width band.
 *
 * That changes what the page feels like more than any table treatment could:
 * an invoice that starts white reads as correspondence, where one that starts
 * with a black band reads as a statement. Both are useful; this is the first
 * of the former.
 *
 * It also ends without a footer. The contact details are already at the top,
 * so repeating them at the bottom would be the same information twice on a
 * page that is trying to stay quiet.
 *
 * The "Due Date" column is the same optional `period` field Arc labels
 * "Period" — one field, two honest labels, no second sum.
 */
const Bright = ({ invoice, t }) => {
  const v = prepare(invoice)

  const details = (invoice.details || []).filter(d => d.label.trim() || d.value.trim())
  const payment = (invoice.payments || []).find(
    p => p.method.trim() || p.reference.trim() || Number(p.amount)
  )
  const anyPeriod = v.lines.some(line => line.period)

  return (
    <div
      className={s.page}
      style={{ "--c": t.primary, "--on-c": t.onPrimary, "--a": t.accent, "--ink": t.ink, "--surface": t.surface }}
    >
      <header className={s.head}>
        <div className={s.issuer}>
          {invoice.from.logo ? (
            <img src={invoice.from.logo} alt="" className={s.logo} />
          ) : invoice.from.name.trim() ? (
            <p className={s.house}>{invoice.from.name}</p>
          ) : null}

          <div className={s.contacts}>
            {invoice.from.phone.trim() ? (
              <p>
                <PhoneIcon />
                {invoice.from.phone}
              </p>
            ) : null}
            {invoice.from.email.trim() ? (
              <p>
                <MailIcon />
                {invoice.from.email}
              </p>
            ) : null}
            {invoice.from.address.trim() ? (
              <p className={s.addr}>
                <PinIcon />
                <span>{invoice.from.address.replace(/\n/g, ", ")}</span>
              </p>
            ) : null}
          </div>
        </div>

        <div className={s.tabWrap}>
          <span className={s.tabShadow} aria-hidden="true" />
          <div className={s.tab}>
            <p className={s.word}>Invoice</p>
            <dl className={s.meta}>
              {invoice.number.trim() ? (
                <>
                  <dt>Invoice No:</dt>
                  <dd>{invoice.number}</dd>
                </>
              ) : null}
              {v.issued ? (
                <>
                  <dt>Invoice Date:</dt>
                  <dd>{v.issued}</dd>
                </>
              ) : null}
              {v.due ? (
                <>
                  <dt>Due Date:</dt>
                  <dd>{v.due}</dd>
                </>
              ) : null}
            </dl>
          </div>
        </div>
      </header>

      <div className={s.body}>
        {details.length > 0 ? (
          <section className={s.stats}>
            {details.slice(0, 6).map(d => (
              <div key={d.id}>
                <span className={s.statLabel}>{d.label}:</span>
                <span className={s.statValue}>{d.value}</span>
              </div>
            ))}
          </section>
        ) : null}

        {invoice.to.name.trim() || invoice.to.address.trim() ? (
          <section className={s.billTo}>
            <p className={s.billLabel}>Bill To:</p>
            {invoice.to.name.trim() ? <p className={s.billName}>{invoice.to.name}</p> : null}
            {invoice.to.address.trim() ? <p className={s.billLine}>{invoice.to.address}</p> : null}
            {invoice.to.email.trim() ? <p className={s.billLine}>{invoice.to.email}</p> : null}
          </section>
        ) : null}

        <table className={s.table}>
          <thead>
            <tr>
              <th className={s.colNo}>Sr. No.</th>
              <th className={s.colDesc}>Details</th>
              {anyPeriod ? <th className={s.colDue}>Due Date</th> : null}
              <th className={s.colAmount}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {v.lines.length === 0 ? (
              <tr>
                <td colSpan={anyPeriod ? 4 : 3} className={s.empty}>
                  No items yet.
                </td>
              </tr>
            ) : (
              v.lines.map((line, i) => (
                <tr key={line.id}>
                  <td className={s.colNo}>{i + 1}</td>
                  <td className={s.colDesc}>
                    <span className={s.itemTitle}>{line.title}</span>
                    {line.rest ? <span className={s.itemRest}>{line.rest}</span> : null}
                  </td>
                  {anyPeriod ? <td className={s.colDue}>{line.period}</td> : null}
                  <td className={s.colAmount}>{v.fmt(line.amount)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <section className={s.mid}>
          <div className={s.payBy}>
            {payment ? (
              <>
                <p className={s.payTitle}>Pay By:</p>
                {payment.method.trim() ? (
                  <p>
                    {payment.method}
                    {payment.reference.trim() ? `: ${payment.reference}` : ""}
                  </p>
                ) : null}
                {Number(payment.amount) ? <p>Amount: {money(payment.amount, v.currency)}</p> : null}
                {payment.date ? <p>Date: {formatDate(payment.date)}</p> : null}
              </>
            ) : null}

            {(invoice.notes.trim() || invoice.terms.trim()) && (
              <div className={s.small}>
                {invoice.notes.trim() ? <p>{invoice.notes}</p> : null}
                {invoice.terms.trim() ? <p>{invoice.terms}</p> : null}
              </div>
            )}
          </div>

          <div className={s.sums}>
            <p>
              <span>Sub Total:</span>
              <span>{v.fmt(v.sums.subtotal)}</span>
            </p>
            {v.hasTax ? (
              <p>
                <span>
                  {v.taxLabel} ({v.taxRate}%)
                </span>
                <span>{v.fmt(v.sums.tax)}</span>
              </p>
            ) : null}
            {v.hasDiscount ? (
              <p>
                <span>Discount{v.discountPct ? ` (${v.discountPct}%)` : ""}</span>
                <span>− {v.fmt(v.sums.discount)}</span>
              </p>
            ) : null}
            {v.hasPaid ? (
              <p>
                <span>Paid:</span>
                <span>− {v.fmt(v.sums.paid)}</span>
              </p>
            ) : null}
            <p className={s.grand}>
              <span>{v.hasPaid ? "Balance Due:" : "Grand Total:"}</span>
              <span>{v.fmt(v.hasPaid ? v.sums.balance : v.sums.total)}</span>
            </p>
          </div>
        </section>
      </div>
    </div>
  )
}

export default Bright
